// This code has been fully generated by an AI.
//
// Pure transformations of an activity stream (see fitfile.Stream) for maps
// and charts. No DOM access, so the module can be tested with node --test.

/** [lon, lat] pairs for all samples with a position. */
export function coordinates(stream) {
  const out = [];
  const { lat, lon } = stream;
  if (!lat || !lon) return out;
  for (let i = 0; i < lat.length; i++) {
    if (lat[i] != null && lon[i] != null) out.push([lon[i], lat[i]]);
  }
  return out;
}

/**
 * Position at sample i, or of the nearest earlier sample with a position
 * (GPS dropouts), as [lon, lat]; null if none.
 */
export function positionAt(stream, i) {
  const { lat, lon } = stream;
  if (!lat || !lon) return null;
  for (let j = Math.min(i, lat.length - 1); j >= 0; j--) {
    if (lat[j] != null && lon[j] != null) return [lon[j], lat[j]];
  }
  return null;
}

/**
 * x axis for charts: distance in km when available (as on most cycling
 * platforms), otherwise elapsed time in minutes. Missing distances are
 * carried forward so the axis stays monotonic for uPlot.
 */
export function xAxis(stream) {
  if (stream.dist?.some((d) => d != null)) {
    let last = 0;
    return {
      label: "Distanz (km)",
      unit: "km",
      values: stream.dist.map((d) => (last = d != null ? Math.max(last, d / 1000) : last)),
    };
  }
  return { label: "Zeit (min)", unit: "min", values: stream.t.map((s) => s / 60) };
}

const scale = (values, f) => values?.map((v) => (v == null ? null : f(v)));

/** Chart definitions for the channels present in the stream. */
export function chartSeries(stream) {
  const defs = [
    { key: "alt", label: "Höhe", unit: "m", color: "#868e96", fill: true, values: stream.alt },
    { key: "speed", label: "Tempo", unit: "km/h", color: "#1c7ed6", values: scale(stream.speed, (v) => v * 3.6) },
    { key: "hr", label: "Herzfrequenz", unit: "bpm", color: "#e03131", values: stream.hr },
    { key: "power", label: "Leistung", unit: "W", color: "#7048e8", values: stream.power },
    { key: "cad", label: "Trittfrequenz", unit: "rpm", color: "#2b8a3e", values: stream.cad },
    { key: "temp", label: "Temperatur", unit: "°C", color: "#f08c00", values: stream.temp },
  ];
  return defs.filter((d) => d.values?.some((v) => v != null));
}

/**
 * Reduces series to at most maxPoints by keeping every n-th sample. Charts
 * stay responsive for multi-hour recordings; the map uses all points.
 */
export function thin(x, series, maxPoints = 4000) {
  const step = Math.max(1, Math.ceil(x.length / maxPoints));
  if (step === 1) return { x, series, index: x.map((_, i) => i) };
  const index = [];
  for (let i = 0; i < x.length; i += step) index.push(i);
  return {
    x: index.map((i) => x[i]),
    series: series.map((s) => ({ ...s, values: index.map((i) => s.values[i]) })),
    index,
  };
}

/**
 * Sample range [first, last] of a section given in seconds since the start
 * (laps, best efforts); null if no sample lies inside.
 */
export function rangeIndices(t, startS, endS) {
  let first = -1;
  let last = -1;
  for (let i = 0; i < t.length; i++) {
    if (t[i] < startS) continue;
    if (t[i] > endS) break;
    if (first < 0) first = i;
    last = i;
  }
  return first < 0 ? null : [first, last];
}

/** Positions of samples first..last as [lon, lat] pairs. */
export function sectionCoordinates(stream, first, last) {
  const out = [];
  const { lat, lon } = stream;
  if (!lat || !lon) return out;
  for (let i = first; i <= last && i < lat.length; i++) {
    if (lat[i] != null && lon[i] != null) out.push([lon[i], lat[i]]);
  }
  return out;
}

/** Index range [k0, k1] of thinned chart samples covering first..last. */
export function thinnedRange(index, first, last) {
  let k0 = -1;
  let k1 = -1;
  for (let k = 0; k < index.length; k++) {
    if (index[k] < first) continue;
    if (index[k] > last) break;
    if (k0 < 0) k0 = k;
    k1 = k;
  }
  return k0 < 0 ? null : [k0, k1];
}
